const body = $input.first().json.body;
const input = body && typeof body === 'object' && !Array.isArray(body) ? body : {};
const codes = [];
const requestId = typeof input.request_id === 'string' ? input.request_id : '';
const question = typeof input.question === 'string' ? input.question.trim() : '';
const user = typeof input.user === 'string' ? input.user.trim() : '';
if (!requestId.trim() || requestId.length > 64) codes.push('invalid_request');
if (!question) codes.push('question_required');
else if (question.length > 500) codes.push('too_long');
if (!user) codes.push('unknown_user');
const attempt = input.attempt === undefined ? 1 : input.attempt;
if (!Number.isInteger(attempt) || attempt < 1) codes.push('invalid_request');
const context = input.context === undefined ? '' : input.context;
if (typeof context !== 'string' || context.length > 2000) codes.push('invalid_request');
if (input.channel !== undefined && typeof input.channel !== 'string') codes.push('invalid_request');
return [{ json: { request_id: requestId, user, clean_question: question, context: typeof context === 'string' ? context : '', attempt, channel: input.channel ?? null, codes: [...new Set(codes)], employee_lookup: 'skipped', triage_mode: 'mock' } }];

const item = $input.first().json;
if (item.codes.length) return [{ json: item }];
// P0-1 Mock of GET /employees. Replace with the provider's response in P1.
const mockResponse = { items: [
  { name: '이준호', dept: '영업팀' },
  { name: '박서연', dept: '재무팀' },
  { name: '최유진', dept: '인사팀' },
  { name: '한지훈', dept: '개발팀' },
  { name: '김민지', dept: 'IT팀' },
  { name: '정우성', dept: 'IT팀' }
] };
if (!Array.isArray(mockResponse.items)) return [{ json: { ...item, employee_lookup: 'unavailable' } }];
const employee = mockResponse.items.find(row => row.name === item.user);
if (!employee) return [{ json: { ...item, codes: ['unknown_user'], employee_lookup: 'not_found' } }];
return [{ json: { ...item, user: employee.name, dept: employee.dept, access_levels: employee.dept === 'IT팀' ? ['all', 'it'] : ['all'], employee_lookup: 'ok' } }];

const item = $input.first().json;
if (item.codes.length || item.employee_lookup !== 'ok') return [{ json: { ...item, blocked: false } }];
const source = `${item.clean_question} ${item.context}`;
const inspect = source.normalize('NFKC').replace(/[\u200B-\u200F\u2060\uFEFF\u0000-\u001F]/g, '').toLowerCase();
const compact = inspect.replace(/[\s\p{P}\p{S}]+/gu, '');
const instructionOverride = /(이전|앞선|위의|previous|prior).{0,24}(지시|명령|instructions?).{0,24}(무시|ignore)/i.test(compact);
const promptDisclosure = /(시스템프롬프트|시스템지시|systemprompt|systeminstructions?)/i.test(compact) && /(보여|공개|출력|알려|revea?l|show|print)/i.test(compact);
const roleSpoofing = /(<\|im_start\|>|\[inst\]|<<sys>>)/i.test(inspect);
return [{ json: { ...item, blocked: (instructionOverride && promptDisclosure) || roleSpoofing } }];

const item = $input.first().json;
// P0-2 deterministic Mock only. It is not an LLM result or a final classifier.
const question = item.clean_question;
const context = item.context;
const combined = `${question} ${context}`;
const compactQuestion = question.replace(/\s+/g, '');
const vagueConnection = /접속이안돼요|접속이안됩니다|접속안돼요/.test(compactQuestion);
const missing = vagueConnection ? [
  ...(/VPN|메일|문서|사내\s*서비스|시스템|앱/.test(combined) ? [] : ['접속 대상']),
  ...(/오류\s*\d+|에러\s*\d+|오류\s*메시지|끊김/.test(context) ? [] : ['오류 메시지']),
  ...(/오늘|어제|오전|오후|부터|시각|시점/.test(context) ? [] : ['발생 시점'])
] : [];
let type = 'other';
if (/피싱|유출|분실|보안\s*사고/.test(combined)) type = 'security';
else if (/VPN|네트워크|와이파이/.test(combined)) type = 'network';
else if (/비밀번호|계정|로그인|인증/.test(combined)) type = 'account';
else if (/메일|문서|개인정보/.test(combined)) type = 'mail_document';
else if (/프린터|기기|회의실|장비/.test(combined)) type = 'device';
else if (/설치|소프트웨어|프로그램/.test(combined)) type = 'software';
const urgent = /피싱.{0,20}(눌렀|클릭)|분실했|유출.{0,10}(의심|됐)|전사\s*장애/.test(combined);
const needsAction = /초기화해|잠금\s*해제해|설치해|현장\s*조치/.test(combined);
const ticketId = combined.match(/T-\d+/)?.[0] ?? null;
const triage = { type, urgency: urgent ? 'high' : 'normal', missing, ticket_id: ticketId, needs_action: needsAction };
return [{ json: { ...item, triage_output: JSON.stringify(triage), triage_mock: true } }];

const base = $('N04 Injection rules').first().json;
const raw = $input.first().json;
const result = { ...base, triage_mode: raw.triage_mock === true ? 'mock' : 'agent', triage_executed: raw.triage_mock !== true };
if (raw.error) return [{ json: { ...result, triage_error: 'llm_down' } }];
let value;
try {
  if (typeof (raw.triage_output ?? raw.output) !== 'string') throw new Error('not_string');
  value = JSON.parse(raw.triage_output ?? raw.output);
  const allowed = ['missing', 'needs_action', 'ticket_id', 'type', 'urgency'];
  if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error('not_object');
  if (JSON.stringify(Object.keys(value).sort()) !== JSON.stringify(allowed)) throw new Error('keys');
  if (!['account', 'network', 'mail_document', 'device', 'software', 'security', 'other'].includes(value.type)) throw new Error('type');
  if (!['normal', 'high'].includes(value.urgency)) throw new Error('urgency');
  if (!Array.isArray(value.missing) || value.missing.some(v => typeof v !== 'string' || !v.trim())) throw new Error('missing');
  if (typeof value.needs_action !== 'boolean') throw new Error('needs_action');
  if (value.ticket_id !== null) {
    if (typeof value.ticket_id !== 'string' || !/^T-\d+$/.test(value.ticket_id)) throw new Error('ticket_id');
    if (!(`${base.clean_question} ${base.context}`).includes(value.ticket_id)) throw new Error('invented_ticket_id');
  }
} catch (_error) {
  return [{ json: { ...result, triage_error: 'triage_invalid' } }];
}
return [{ json: { ...result, triage: value, triage_error: null } }];

const item = $input.first().json;
if (item.triage_error) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: item.triage_error } }];
const triage = item.triage;
if (triage.urgency === 'high') return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'urgent', priority: 'high' } }];
if (triage.needs_action) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'action_required', priority: 'normal' } }];
if (triage.missing.length && item.attempt >= 3) return [{ json: { ...item, decision: 'handoff_mock', decision_reason: 'max_attempts', priority: 'normal' } }];
if (triage.missing.length) {
  const questions = { '접속 대상': '접속 대상은 무엇인가요?', '오류 메시지': '어떤 오류 메시지가 표시되나요?', '발생 시점': '언제부터 발생했나요?' };
  const answer = triage.missing.map(value => questions[value] ?? `${value}을 알려주세요.`).join(' ');
  return [{ json: { ...item, decision: 'clarify', answer } }];
}
return [{ json: { ...item, decision: 'pending' } }];

const item = $input.first().json;
if (item.codes.length) return [{ json: { status_code: 400, response: { error: 'invalid request', codes: item.codes } } }];
const common = { request_id: item.request_id, sources: [], ticket: null, agents: item.triage_executed ? ['triage'] : [], security: { blocked_by: '', reason: '', masked: 0 } };
if (item.employee_lookup !== 'ok') return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '직원 정보를 확인하지 못해 접수하지 못했습니다. 잠시 후 다시 시도해 주세요.', reason: 'identity_unavailable' } } }];
if (item.blocked) return [{ json: { status_code: 200, response: { ...common, route: '차단', answer: '보안 정책상 처리할 수 없는 요청입니다. IT 문의 창구로 연락해 주세요.', security: { blocked_by: 'rule', reason: 'prompt_injection', masked: 0 } } } }];
if (item.decision === 'clarify') return [{ json: { status_code: 200, response: { ...common, route: '보완 질문', answer: item.answer } } }];
if (item.decision === 'handoff_mock') return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '개발 중이며 접수하지 않았습니다.', reason: 'not_implemented' } } }];
return [{ json: { status_code: 200, response: { ...common, route: '담당자 이관', answer: '개발 중이며 접수하지 않았습니다.', reason: 'not_implemented' } } }];
